const sandGolemSheet=new Image();sandGolemSheet.assetSrc='assets/desert-sand-golem-v1.png';
function beginSandGolem(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'sandQuakeRings',bespoke:true,windup:.9,origin:{x:e.x,y:e.y},waves:0};let dx=p.x-e.x,dy=p.y-e.y;e.facing=dx-dy<0?-1:1;}
function sandGolemBandContains(origin,index,point){let radius=dist(origin,point);return radius<=(index+1)*80+1e-8&&(index===0||radius>index*80+1e-8);}
const sandGolemAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{if(e.species!=='r4e4')return sandGolemAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='sandQuakeRings'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=260&&clear)beginSandGolem(e);else{e.state='idle';if(distance>750&&!e.aware)return;if(distance<=170&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,65*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 let a=e.attack;if(dist(e,a.origin)>30){e.attack=null;e.state='idle';e.t=1.4;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;while(a.waves<3&&e.elapsed>=.9+a.waves*.5){let index=a.waves++;e.struck=true;if(sandGolemBandContains(a.origin,index,p)&&lineClear(a.origin,p))hurt(64);playSound('impact',a.origin.x,a.origin.y);}
 if(e.elapsed>=2.7){e.attack=null;e.state='idle';e.t=2.8;}
};
const sandGolemDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r4e4'||!sandGolemSheet.complete||!sandGolemSheet.naturalWidth||!sandGolemSheet.naturalHeight)return sandGolemDrawBase(e,size);let f=spriteFrame(e.hp<=0?'idle':e.state,e.hp<=0?0:e.anim);if(e.hp>0&&e.attack?.pattern==='sandQuakeRings')f={row:2,col:e.elapsed<.45?0:e.elapsed<.9?1:e.elapsed<1.9?2:3};let q=project(e.x,e.y),sw=sandGolemSheet.naturalWidth/4,sh=sandGolemSheet.naturalHeight/3,w=170,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';let anchor=f.row===2?.95:.92;if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,sandGolemSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(sandGolemSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const sandGolemSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r4e4'?112:sandGolemSizeBase(e);
function paintSandGolemBand(origin,index,fired){let q=project(origin.x,origin.y),inner=index*80,outer=(index+1)*80;ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=fired?'#ffdb9c55':'#e6a96524';ctx.strokeStyle=fired?'#fff1ce':'#e9bc78';ctx.lineWidth=fired?3:2;ctx.beginPath();ctx.arc(0,0,outer,0,Math.PI*2);if(inner){ctx.moveTo(inner,0);ctx.arc(0,0,inner,0,Math.PI*2,true);}ctx.fill();ctx.stroke();ctx.restore();}
const sandGolemGroundBase=drawGroundEffects;drawGroundEffects=()=>{sandGolemGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r4e4'):enemies)){let a=e.attack;if(e.species!=='r4e4'||e.hp<=0||a?.pattern!=='sandQuakeRings'||!visibleAt(a.origin.x,a.origin.y))continue;let flash=a.waves>0&&e.elapsed<.9+(a.waves-1)*.5+.18;if(a.waves<3){for(let i=a.waves+1;i<3;i++)groundRing(a.origin.x,a.origin.y,(i+1)*80,'#b3935d66',1);paintSandGolemBand(a.origin,a.waves,false);}if(flash)paintSandGolemBand(a.origin,a.waves-1,true);}};
